            'exigir servidor de banco externo.\n'
            '10. A configuração do DbContext deve utilizar UseSqlite e uma connection string com '
            'Data Source apontando para o arquivo local.\n'
            '11. O arquivo do banco deve ficar em diretório de dados da aplicação, não dentro de '
            'diretórios temporários.\n'
            '12. A inicialização deve criar/atualizar o esquema de forma compatível com o projeto '
            'e preservar os dados existentes.\n'
            '\n'
            '9. xUnit deve ser utilizado nos testes automatizados do backend.\n'
            '\n'
            '10. Não substituir nenhuma tecnologia obrigatória.\n'
            '\n'
            '11. Caso alguma decisão adicional seja necessária,\n'
