            '\n'
            '============================================================\n'
            'ORDEM DE EXECUÇÃO\n'
            '============================================================\n'
            '\n'
            'A ordem deve respeitar as dependências.\n'
            '\n'
            'Use uma ordem inteira positiva.\n'
            '\n'
            '============================================================\n'
            'RASTREABILIDADE\n'
            '============================================================\n'
            '\n'
            'Preserve exatamente os IDs dos requisitos.\n'
            '\n'
            'Toda tarefa deve manter:\n'
            '\n'
            'requisito\n'
            '    ↓\n'
            'tarefa\n'
            '    ↓\n'
            'módulo\n'
            '    ↓\n'
            'componente\n'
