            '                codigo_por_arquivo[caminho] = atualizado\n'
            '        init_corrigida = estrategia_manter\n'
            '        tem_migrate = estrategia_manter == "migrations"\n'
            '        tem_ensure = estrategia_manter == "EnsureCreated"\n'
            '\n'
            '    # Se ainda não existir estratégia, escolhe a abordagem compatível com os\n'
            '    # artefatos presentes. Não tenta combinar inicialização de vários DbContexts\n'
            '    # numa base compartilhada: nesse caso a validação pede reparo explícito.\n'
            '    if not tem_migrate and not tem_ensure and len(dbcontexts_unicos) == 1:\n'
            '        classe, namespace, tipo_full = dbcontexts_unicos[0]\n'
            '        tipo = f"global::{namespace}.{classe}" if namespace else classe\n'
            '        metodo_init = "Migrate" if migrations_dir else "EnsureCreated"\n'
            '        match_app = '
