            '                "\\nusing (var scope = app.Services.CreateScope())\\n"\n'
            '                "{\\n"\n'
            '                f"    var db = '
            'scope.ServiceProvider.GetRequiredService<{tipo}>();\\n"\n'
            '                f"    db.Database.{metodo_init}();\\n"\n'
            '                "}\\n"\n'
            '            )\n'
            '            texto = texto[:match_app.end()] + inicializador + '
            'texto[match_app.end():]\n'
            '            tem_migrate = metodo_init == "Migrate"\n'
            '            tem_ensure = metodo_init == "EnsureCreated"\n'
            '            init_corrigida = metodo_init + " (inicialização adicionada)"\n'
            '\n'
            '    if "using Microsoft.EntityFrameworkCore;" not in texto:\n'
            '        texto = "using Microsoft.EntityFrameworkCore;\\n" + texto\n'
            '    if "using Microsoft.Data.Sqlite;" not in texto:\n'
            '        texto = "using Microsoft.Data.Sqlite;\\n" + texto\n'
            '\n'
            '    # Cria path absoluto a partir do diretório-base do aplicativo e uma connection '
            'string única.\n'
            '    match_builder = re.search(\n'
            '        '
            'r"(?s)var\\s+builder\\s*=\\s*WebApplication\\.CreateBuilder\\s*\\([^;]*?\\)\\s*;",\n'
            '        texto\n'
            '    )\n'
            '    if not match_builder:\n'
            '        raise RuntimeError("Program.cs não contém o padrão var builder = '
            'WebApplication.CreateBuilder(...);")\n'
            '\n'
            '    bloco = [\n'
            '        "// BEGIN AUTO-GENERATED BACKEND SQLITE AND CORS",\n'
            "        'var dataDirectory = System.IO.Path.Combine(System.AppContext.BaseDirectory, "
            '"Data");\',\n'
            '        "System.IO.Directory.CreateDirectory(dataDirectory);",\n'
            "        'var absoluteDatabasePath = "
            'System.IO.Path.GetFullPath(System.IO.Path.Combine(dataDirectory, '
            '"marcenaria.db"));\',\n'
            "        'var configuredConnectionString = "
            'builder.Configuration.GetConnectionString("DefaultConnection") ?? "Data '
            'Source=marcenaria.db";\',\n'
            '        "var sqliteConnectionString = new '
            'Microsoft.Data.Sqlite.SqliteConnectionStringBuilder(configuredConnectionString)",\n'
            '        "{",\n'
            '        "    DataSource = absoluteDatabasePath",\n'
            '        "}.ToString();",\n'
            '    ]\n'
            '    for classe, namespace, tipo_full in dbcontexts_unicos:\n'
            '        tipo = f"global::{namespace}.{classe}" if namespace else classe\n'
            '        bloco.append(f"builder.Services.AddDbContext<{tipo}>(options => '
            'options.UseSqlite(sqliteConnectionString));")\n'
            '\n'
            '    # Registra serviços apenas se ainda não houver registration para o '
            'tipo/implementação.\n'
            '    for interface, classe, namespace in list(dict.fromkeys(implementacoes)):\n'
