 {'index': 65,
  'section': 'prepara_projeto_frontend',
  'source': 'import os\n'
            'import shutil\n'
            'import subprocess\n'
            'import threading\n'
            'import queue\n'
            'import time\n'
            '\n'
            '\n'
            'def executar_npm(argumentos, cwd=None, timeout=300, env_extra=None):\n'
            '    """Executa npm com saída em tempo real e timeout que não depende de '
            'readline()."""\n'
            '    npm_executavel = shutil.which("npm") or shutil.which("npm.cmd")\n'
            '    if not npm_executavel:\n'
            '        raise RuntimeError("npm não encontrado no PATH do processo FastAPI.")\n'
            '\n'
            '    env = os.environ.copy()\n'
            '    env.update({\n'
            '        "CI": "1",\n'
            '        "npm_config_yes": "true",\n'
            '        "npm_config_audit": "false",\n'
            '        "npm_config_fund": "false",\n'
            '        "npm_config_update_notifier": "false",\n'
            '    })\n'
            '    if env_extra:\n'
            '        env.update(env_extra)\n'
            '\n'
            '    if os.name == "nt" and npm_executavel.lower().endswith((".cmd", ".bat")):\n'
            '        comando = subprocess.list2cmdline([npm_executavel, *argumentos])\n'
            '        processo = subprocess.Popen(\n'
            '            comando, cwd=cwd, env=env, stdout=subprocess.PIPE,\n'
            '            stderr=subprocess.STDOUT, text=True, encoding="utf-8",\n'
            '            errors="replace", shell=True, bufsize=1\n'
            '        )\n'
            '    else:\n'
            '        processo = subprocess.Popen(\n'
            '            [npm_executavel, *argumentos], cwd=cwd, env=env,\n'
            '            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,\n'
            '            encoding="utf-8", errors="replace", bufsize=1\n'
            '        )\n'
            '\n'
            '    linhas = []\n'
            '    fila = queue.Queue()\n'
            '\n'
            '    def _ler_saida():\n'
            '        try:\n'
            '            if processo.stdout:\n'
            '                for linha in iter(processo.stdout.readline, ""):\n'
            '                    fila.put(linha)\n'
            '        finally:\n'
            '            fila.put(None)\n'
            '\n'
            '    leitor = threading.Thread(target=_ler_saida, daemon=True)\n'
            '    leitor.start()\n'
            '    inicio = time.monotonic()\n'
            '    fim_saida = False\n'
            '    try:\n'
            '        while True:\n'
            '            restante = timeout - (time.monotonic() - inicio)\n'
            '            if restante <= 0:\n'
            '                processo.kill()\n'
            '                try:\n'
            '                    processo.wait(timeout=5)\n'
            '                except subprocess.TimeoutExpired:\n'
            '                    pass\n'
            '                raise TimeoutError(\n'
            '                    f"npm excedeu {timeout}s. Últimas '
            'linhas:\\\\n{\'\'.join(linhas[-30:])}"\n'
            '                )\n'
            '            try:\n'
            '                item = fila.get(timeout=min(0.2, restante))\n'
            '                if item is None:\n'
            '                    fim_saida = True\n'
            '                else:\n'
            '                    print(item, end="", flush=True)\n'
            '                    linhas.append(item)\n'
            '            except queue.Empty:\n'
            '                pass\n'
            '\n'
            '            codigo = processo.poll()\n'
            '            if codigo is not None and fim_saida:\n'
            '                break\n'
            '\n'
            '        codigo = processo.wait(timeout=5)\n'
            '    finally:\n'
            '        if processo.poll() is None:\n'
            '            processo.kill()\n'
            '            try:\n'
            '                processo.wait(timeout=5)\n'
            '            except subprocess.TimeoutExpired:\n'
            '                pass\n'
            '        if processo.stdout:\n'
            '            processo.stdout.close()\n'
            '\n'
            '    class Resultado:\n'
            '        def __init__(self, returncode, stdout):\n'
            '            self.returncode = returncode\n'
            '            self.stdout = stdout\n'
            '            self.stderr = ""\n'
            '\n'
            '    return Resultado(codigo, "".join(linhas))\n'
            '\n'
            '\n'
            'def verificar_node_npm():\n'
            '    node = shutil.which("node") or shutil.which("node.exe")\n'
            '    if not node:\n'
            '        raise RuntimeError("Node.js não encontrado no PATH do processo FastAPI.")\n'
            '    node_resultado = subprocess.run(\n'
            '        [node, "--version"], capture_output=True, text=True, check=False, timeout=15\n'
            '    )\n'
            '    if node_resultado.returncode != 0:\n'
            '        raise RuntimeError(f"Falha ao executar Node.js: '
            '{node_resultado.stderr.strip()}")\n'
            '    npm_resultado = executar_npm(["--version"], timeout=15)\n'
            '    if npm_resultado.returncode != 0:\n'
            '        raise RuntimeError("Falha ao executar npm --version.")\n'
            '    print(f"✓ Node.js: {node_resultado.stdout.strip()} ({node})")\n'
            '    print(f"✓ npm: {npm_resultado.stdout.strip()}")\n'
            '    return node_resultado.stdout.strip(), npm_resultado.stdout.strip()\n'},
 {'index': 66,
  'section': 'prepara_projeto_frontend',
  'source': 'def criar_projeto_react(frontend_dir):\n'
            '    """Cria o esqueleto React + TypeScript; saída do npm é exibida em tempo real."""\n'
            '    frontend_dir = os.path.abspath(frontend_dir)\n'
            '    package_json = os.path.join(frontend_dir, "package.json")\n'
            '    if os.path.exists(package_json):\n'
            '        print("✓ Projeto React já existe.")\n'
            '        return frontend_dir\n'
            '\n'
            '    os.makedirs(frontend_dir, exist_ok=True)\n'
            '    # Evita recriar sobre arquivos já existentes: Vite pode abrir prompt nesse caso.\n'
            '    existentes = [nome for nome in os.listdir(frontend_dir) if nome not in '
            '("desktop.ini",)]\n'
            '    if existentes:\n'
            '        raise RuntimeError(\n'
            '            f"A pasta frontend existe e não está vazia, mas não contém package.json: '
            '"\n'
            '            f"{frontend_dir}. Conteúdo: {existentes[:20]}"\n'
            '        )\n'
            '\n'
            '    print("🚀 Criando projeto React + TypeScript via Vite...")\n'
            '    resultado = executar_npm(\n'
            '        ["create", "vite@latest", ".", "--", "--template", "react-ts", '
            '"--no-interactive", "--no-rolldown", "--eslint"],\n'
            '        cwd=frontend_dir,\n'
            '        timeout=300,\n'
            '    )\n'
            '    if resultado.returncode != 0:\n'
            '        raise RuntimeError(\n'
            '            f"Falha ao criar projeto React (código {resultado.returncode}). "\n'
            '            f"Confira a saída do npm exibida acima."\n'
            '        )\n'
            '    if not os.path.isfile(package_json):\n'
            '        raise RuntimeError(\n'
            '            "O comando Vite terminou, mas package.json não foi criado. "\n'
            '            "Verifique a conectividade com o registry npm e a saída anterior."\n'
            '        )\n'
            '    print("✓ Projeto React criado.")\n'
            '    return frontend_dir\n'},
