            '    limite_caracteres=50000\n'
            '):\n'
            '    arquivos = []\n'
            '\n'
            '    for raiz, _, nomes in os.walk(frontend_dir):\n'
            '\n'
            '        if "node_modules" in raiz.split(os.sep):\n'
            '            continue\n'
            '\n'
            '        for nome in nomes:\n'
            '\n'
            '            if not nome.endswith((\n'
            '                ".ts",\n'
            '                ".tsx",\n'
            '                ".css"\n'
            '            )):\n'
            '                continue\n'
            '\n'
            '            caminho = os.path.join(\n'
            '                raiz,\n'
            '                nome\n'
            '            )\n'
            '\n'
            '            relativo = os.path.relpath(\n'
            '                caminho,\n'
            '                frontend_dir\n'
            '            )\n'
            '\n'
            '            try:\n'
            '                with open(\n'
            '                    caminho,\n'
            '                    "r",\n'
            '                    encoding="utf-8"\n'
            '                ) as f:\n'
            '                    conteudo = f.read()\n'
            '\n'
            '                arquivos.append({\n'
            '                    "caminho": relativo,\n'
