            '        ):\n'
            '            tarefas.append(tarefa)\n'
            '\n'
            '    tarefas = sorted(\n'
            '        tarefas,\n'
            '        key=lambda x: x.ordem_execucao\n'
            '    )\n'
            '\n'
            '    # Validação final: não permitir que o pipeline frontend\n'
            '    # seja executado silenciosamente com zero tarefas.\n'
            '    if not tarefas:\n'
            '        raise ValueError(\n'
            '            "Nenhuma tarefa frontend disponível no Plano de "\n'
