            '\n'
            'def executar_tasks_frontend(\n'
            '    tarefas_frontend,\n'
            '    agente_frontend,\n'
            '    projeto,\n'
            '    requisitos_funcionais,\n'
            '    requisitos_nao_funcionais,\n'
            '    regras_negocio,\n'
            '    analise,\n'
            '    arquitetura,\n'
            '    frontend_dir\n'
            '):\n'
            '\n'
            '    resultados = []\n'
            '    tarefas_com_erro = []\n'
            '\n'
            '    # Retomada: reaproveita tasks já concluídas e persistidas no disco.\n'
            '    # Tasks BLOQUEADO/PARCIAL não são ignoradas; serão tentadas novamente.\n'
            '    resultados_dir = os.path.join(frontend_dir, "_resultados")\n'
            '    os.makedirs(resultados_dir, exist_ok=True)\n'
            '    tarefas_concluidas = set()\n'
            '\n'
            '    for tarefa_salva in os.listdir(resultados_dir):\n'
            '        if not tarefa_salva.lower().endswith(".json"):\n'
