            '            if resultado_salvo.status == "CONCLUIDO":\n'
            '                resultados.append(resultado_salvo)\n'
            '                tarefas_concluidas.add(resultado_salvo.task_id)\n'
            '        except Exception as erro:\n'
            '            print(f"⚠️ Resultado salvo ignorado ({tarefa_salva}): {erro}")\n'
            '\n'
            '    # ============================================================\n'
            '    # EXECUÇÃO SEQUENCIAL\n'
            '    # ============================================================\n'
            '\n'
            '    for indice, tarefa in enumerate(\n'
            '        tarefas_frontend,\n'
            '        start=1\n'
            '    ):\n'
            '\n'
            '        print("\\n")\n'
            '        print("=" * 80)\n'
            '\n'
            '        print(\n'
