 {'index': 97,
  'section': 'agente_teste',
  'source': '\n'
            '\n'
            'import subprocess\n'
            'import time\n'
            'from datetime import datetime, timezone\n'
            '\n'
            '\n'
            'def executar_comando_teste(\n'
            '    comando,\n'
            '    diretorio,\n'
            '    nome,\n'
            '    timeout=600\n'
            '):\n'
            '    inicio = datetime.now(timezone.utc).isoformat()\n'
            '    instante = time.time()\n'
            '\n'
            '    try:\n'
            '        resultado = subprocess.run(\n'
            '            comando,\n'
            '            cwd=diretorio,\n'
            '            capture_output=True,\n'
            '            text=True,\n'
            '            timeout=timeout\n'
            '        )\n'
            '\n'
            '        registro = {\n'
            '            "nome": nome,\n'
            '            "comando": comando,\n'
            '            "diretorio": diretorio,\n'
            '            "inicio_utc": inicio,\n'
            '            "duracao_segundos": round(\n'
            '                time.time() - instante, 2\n'
            '            ),\n'
            '            "codigo_saida": resultado.returncode,\n'
            '            "status": (\n'
            '                "APROVADO"\n'
            '                if resultado.returncode == 0\n'
            '                else "REPROVADO"\n'
            '            ),\n'
            '            "stdout": resultado.stdout,\n'
            '            "stderr": resultado.stderr\n'
            '        }\n'
            '\n'
            '    except subprocess.TimeoutExpired as erro:\n'
            '        registro = {\n'
            '            "nome": nome,\n'
            '            "comando": comando,\n'
            '            "diretorio": diretorio,\n'
            '            "inicio_utc": inicio,\n'
            '            "duracao_segundos": round(\n'
            '                time.time() - instante, 2\n'
            '            ),\n'
            '            "codigo_saida": None,\n'
            '            "status": "BLOQUEADO",\n'
            '            "stdout": erro.stdout or "",\n'
            '            "stderr": erro.stderr or "",\n'
            '            "motivo": "Tempo limite excedido."\n'
            '        }\n'
            '\n'
            '    except Exception as erro:\n'
            '        registro = {\n'
            '            "nome": nome,\n'
            '            "comando": comando,\n'
            '            "diretorio": diretorio,\n'
            '            "inicio_utc": inicio,\n'
            '            "duracao_segundos": round(\n'
            '                time.time() - instante, 2\n'
            '            ),\n'
            '            "codigo_saida": None,\n'
            '            "status": "BLOQUEADO",\n'
            '            "stdout": "",\n'
            '            "stderr": str(erro),\n'
            '            "motivo": "Não foi possível executar o comando."\n'
            '        }\n'
            '\n'
            '    print(\n'
            '        f"{registro[\'status\']}: {nome} "\n'
            '        f"(código={registro[\'codigo_saida\']})"\n'
            '    )\n'
            '\n'
            '    if registro["stdout"]:\n'
            '        print(registro["stdout"][-4000:])\n'
            '\n'
            '    if registro["stderr"]:\n'
            '        print(registro["stderr"][-4000:])\n'
            '\n'
            '    return registro\n'
            '\n'},
 {'index': 98,
  'section': 'agente_teste',
  'source': '\n'
            '\n'
            'def executar_validacoes_backend(\n'
            '    backend_dir,\n'
            '    caminho_projeto_testes=None\n'
            '):\n'
            '    resultados = []\n'
            '\n'
            '    resultados.append(\n'
            '        executar_comando_teste(\n'
            '            ["dotnet", "build"],\n'
            '            backend_dir,\n'
            '            "backend_build"\n'
            '        )\n'
            '    )\n'
            '\n'
            '    # Só executa os testes se o backend compilar.\n'
            '    if resultados[-1]["status"] == "APROVADO":\n'
            '\n'
            '        if caminho_projeto_testes is None:\n'
            '            caminho_projeto_testes = os.path.join(\n'
            '                backend_dir,\n'
            '                "Tests",\n'
            '                "backend.Tests.csproj"\n'
            '            )\n'
            '\n'
            '        if os.path.isfile(caminho_projeto_testes):\n'
            '            resultados.append(\n'
            '                executar_comando_teste(\n'
            '                    [\n'
            '                        "dotnet",\n'
            '                        "test",\n'
            '                        caminho_projeto_testes\n'
            '                    ],\n'
            '                    backend_dir,\n'
            '                    "backend_testes"\n'
            '                )\n'
            '            )\n'
            '        else:\n'
            '            resultados.append({\n'
            '                "nome": "backend_testes",\n'
            '                "status": "BLOQUEADO",\n'
            '                "codigo_saida": None,\n'
            '                "stdout": "",\n'
            '                "stderr": "",\n'
            '                "motivo": (\n'
            '                    "Projeto de testes não encontrado: "\n'
            '                    f"{caminho_projeto_testes}"\n'
            '                )\n'
            '            })\n'
            '\n'
            '    else:\n'
            '        resultados.append({\n'
            '            "nome": "backend_testes",\n'
            '            "status": "NAO_EXECUTADO",\n'
            '            "codigo_saida": None,\n'
            '            "stdout": "",\n'
            '            "stderr": "",\n'
            '            "motivo": (\n'
            '                "Testes não executados porque o backend "\n'
            '                "não compilou."\n'
            '            )\n'
            '        })\n'
            '\n'
            '    return resultados\n'
            '\n'},
