 {'index': 100,
  'section': 'agente_teste',
  'source': '\n'
            '\n'
            'def validar_tasks_teste_executadas(\n'
            '    tarefas_teste,\n'
            '    resultados_teste\n'
            '):\n'
            '    esperadas = {\n'
            '        tarefa.id\n'
            '        for tarefa in tarefas_teste\n'
            '    }\n'
            '\n'
            '    executadas = {\n'
            '        resultado.task_id\n'
            '        for resultado in resultados_teste\n'
            '    }\n'
            '\n'
            '    faltantes = sorted(esperadas - executadas)\n'
            '    inesperadas = sorted(executadas - esperadas)\n'
            '\n'
            '    com_falha = sorted(\n'
            '        resultado.task_id\n'
            '        for resultado in resultados_teste\n'
            '        if resultado.status in {"PARCIAL", "BLOQUEADO"}\n'
            '    )\n'
            '\n'
            '    concluidas = sorted(\n'
            '        resultado.task_id\n'
            '        for resultado in resultados_teste\n'
            '        if resultado.status == "CONCLUIDO"\n'
            '    )\n'
            '\n'
            '    total = len(esperadas)\n'
            '\n'
            '    percentual = (\n'
            '        len(concluidas) / total * 100\n'
            '        if total\n'
            '        else 100.0\n'
            '    )\n'
            '\n'
            '    return {\n'
            '        "valido": (\n'
            '            not faltantes\n'
            '            and not inesperadas\n'
            '            and not com_falha\n'
            '            and esperadas == executadas\n'
            '        ),\n'
            '        "total_planejadas": total,\n'
            '        "total_concluidas": len(concluidas),\n'
            '        "faltantes": faltantes,\n'
            '        "inesperadas": inesperadas,\n'
            '        "com_falha": com_falha,\n'
            '        "percentual_conclusao": round(percentual, 2)\n'
            '    }\n'
            '\n'},
